template <typename T, typename Cleanup = ScopedPtrDeleter<T> >
class ScopedPtr
{
public:
  explicit inline ScopedPtr(T *p = 0) : d(p)
  {
  }

  inline ~ScopedPtr()
  {
    T *oldD = this->d;
    try
    {
      Cleanup::cleanup(oldD);
    }
    catch(...)
    {
      //some bad happen
    }

    this->d = 0;
  }

  inline T& operator*() const
  {
    _GAME_DEBUG_BREAK_IF( !d );
    return *d;
  }

  inline T *operator->() const
  {
    _GAME_DEBUG_BREAK_IF( !d );
    return d;
  }

  inline bool operator!() const {		return !d;	}
  inline operator bool() const {	return !isNull();	}
  inline T* data() const	{	return d;	}
  inline bool isNull() const { return !d; }

  template<typename... Args>
  void createInstance( Args & ... args)
  {
    T* instance = new T( args... );
    reset( instance );
  }

  inline void reset(T *other = 0)
  {
    if (d == other)
      return;

    T *oldD = d;
    d = other;
    try
    {
      Cleanup::cleanup(oldD);
    }
    catch(...)
    {
      //some bad happen
    }
  }

  inline T *take()
  {
    T *oldD = d;
    d = 0;
    return oldD;
  }

  inline void swap(ScopedPtr<T, Cleanup> &other)
  {
    std::swap(d, other.d);
  }

  typedef T *pointer;

protected:
  T *d;

private:
  __DISABLE_COPY(ScopedPtr)
};

